export interface RecordFormats {
  readonly brief: { readonly key: string; readonly label: string };
  readonly full: { readonly key: string; readonly label: string; readonly tags: readonly string[] };
}

function objectValue(value: unknown): Record<string, unknown> {
  if (typeof value !== "object" || value === null || Array.isArray(value)) {
    throw new TypeError("Malformed record");
  }
  return value as Record<string, unknown>;
}

export function decodeRecord<F extends keyof RecordFormats>(format: F, input: unknown): RecordFormats[F] {
  const value = objectValue(input);
  if (typeof value.key !== "string" || typeof value.label !== "string") {
    throw new TypeError("Malformed record");
  }
  if (format === "brief") {
    return { key: value.key, label: value.label } as RecordFormats[F];
  }
  if (!Array.isArray(value.tags) || !value.tags.every((tag) => typeof tag === "string")) {
    throw new TypeError("Malformed record");
  }
  return { key: value.key, label: value.label, tags: value.tags } as RecordFormats[F];
}
```

