import { decodeRecord, RecordFormats } from "./solution";

function assert(condition: boolean, message: string): void {
  if (!condition) throw new Error(message);
}
function equal(actual: unknown, expected: unknown, message: string): void {
  if (!Object.is(actual, expected)) throw new Error(`${message}: expected ${String(expected)}, got ${String(actual)}`);
}
function malformed(fn: () => unknown, message: string): void {
  try { fn(); } catch (error) {
    if (error instanceof TypeError && error.message === "Malformed record") return;
    throw new Error(`${message}: wrong error`);
  }
  throw new Error(`${message}: did not throw`);
}

const briefInput = { key: "", label: "", extra: 17, tags: "ignored" };
const brief: RecordFormats["brief"] = decodeRecord("brief", briefInput);
equal(brief.key, "", "empty brief key accepted");
equal(brief.label, "", "empty brief label accepted");
equal(Object.keys(brief).length, 2, "extra brief fields ignored");
assert(brief !== briefInput, "brief result is fresh");
equal(briefInput.extra, 17, "brief input not mutated");

const tags = ["a", "a", "", "b"];
const fullInput = { key: "k", label: "label", tags, ignored: true };
const full: RecordFormats["full"] = decodeRecord("full", fullInput);
equal(full.key, "k", "full key");
equal(full.label, "label", "full label");
equal(full.tags.length, 4, "tag count");
equal(full.tags[0], "a", "tag order first");
equal(full.tags[1], "a", "duplicate tag preserved");
equal(full.tags[2], "", "empty tag string accepted");
equal(full.tags[3], "b", "tag order last");
assert(full !== fullInput, "full result is fresh");
assert(full.tags !== tags, "tag array copied");
tags[0] = "changed";
tags.push("later");
equal(full.tags[0], "a", "result isolated from input tag mutation");
equal(full.tags.length, 4, "result tag length isolated");
(full.tags as string[])[1] = "result change";
equal(fullInput.tags[1], "a", "input isolated from result mutation");

const emptyFull = decodeRecord("full", { key: "", label: "", tags: [] });
equal(emptyFull.tags.length, 0, "empty tag array accepted");

for (const value of [null, undefined, 1, "x", [], true]) malformed(() => decodeRecord("brief", value), `invalid object ${String(value)}`);
malformed(() => decodeRecord("brief", { key: 1, label: "x" }), "non-string key");
malformed(() => decodeRecord("brief", { key: "x" }), "missing label");
malformed(() => decodeRecord("full", { key: "x", label: "y" }), "missing tags");
malformed(() => decodeRecord("full", { key: "x", label: "y", tags: "a" }), "non-array tags");
malformed(() => decodeRecord("full", { key: "x", label: "y", tags: ["a", 2] }), "non-string tag");

